SELECT 'gongkao', '接待安排类', 'kp-ms-org-reception', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "计划组织：接待安排类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "热情周到但不超标。细节决定成败。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、答题细节"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "食宿安排：提前了解对方的民族禁忌（如清真）、饮食习惯（是否有糖尿病/痛风）和交通方式，严格按照【中央八项规定】标准安排，不铺张浪费。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "行程对接：制定详尽的行程手册，包含时间、地点、对接人电话，提前发给对方。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "突发预案：准备好备用车辆、急救医疗箱、雨具，应对天气变化或突发疾病。"}]}]}]}]}$$ AS jsonb), NULL, '接待安排类的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "计划组织", "接待"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_org_reception", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
